+import Foundation
+import ObjectiveC.runtime
+
+let frameworkPath = "/Applications/Xcode.app/Contents/Developer/Library/PrivateFrameworks/SimulatorKit.framework/SimulatorKit"
+let handle = dlopen(frameworkPath, RTLD_NOW | RTLD_LOCAL)
+if handle == nil {
+    fputs("failed to dlopen SimulatorKit\n", stderr)
+    exit(1)
+}
+
+var classCount: UInt32 = 0
+guard let classes = objc_copyClassList(&classCount) else {
+    fputs("no classes\n", stderr)
+    exit(1)
+}
+
+for i in 0..<Int(classCount) {
+    let cls: AnyClass = classes[i]
+    let name = String(cString: class_getName(cls))
+    guard name.contains("SimDeviceHID") || name.contains("Digitizer") || name.contains("Touch") else { continue }
+    print("CLASS \(name)")
+
+    var methodCount: UInt32 = 0
+    if let methods = class_copyMethodList(cls, &methodCount) {
+        for j in 0..<Int(methodCount) {
+            let sel = method_getName(methods[j])
+            print("  - \(NSStringFromSelector(sel))")
+        }
+        free(methods)
+    }
+}
+
+free(classes)
*** End Patch

